package edu.campusconnect.exception;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.Map;@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(EventFullException.class) public ResponseEntity<Map<String,String>> full(EventFullException e){return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("message",e.getMessage()));}@ExceptionHandler(IllegalArgumentException.class) public ResponseEntity<Map<String,String>> invalid(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}}